import{_ as a,o as i,c as s,a2 as n}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Learning spells","description":"","frontmatter":{},"headers":[],"relativePath":"guide/magic/learning-spells.md","filePath":"guide/magic/learning-spells.md"}'),t={name:"guide/magic/learning-spells.md"};function r(l,e,o,d,p,c){return i(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="learning-spells" tabindex="-1">Learning spells <a class="header-anchor" href="#learning-spells" aria-label="Permalink to &quot;Learning spells&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> <strong>Implementation:</strong> this redesign is not established as implemented. <strong>Availability:</strong> not established as live. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-09 against Batch 04.</p><p><a href="/Syrolands-Public/game-design/magic/spell-knowledge.html">Full design specification</a></p><p>Knowing a spell and having enough Magery to use it reliably are different achievements. Reaching a skill threshold would not automatically unlock a spell or guarantee success.</p><p>A Core Pattern is the learned identity of a spell, such as an illustrative Fireball or Remove Curse. Teachers, academies, cultures, ruins, manuscripts, magical sites, creatures, rituals and experimentation could expand your knowledge. Appropriate player teaching remains a possibility with rules still to design.</p><p>Familiarity grows around individual patterns rather than spending more skillcap. Wider schools and specialization remain distinct. <a href="/Syrolands-Public/guide/magic/memory-and-familiarity.html">Active Memory</a> determines prepared access; an ordinary casting scroll does not permanently teach its spell.</p><p>The proposal retains useful early magic and long-term discovery. Exact learning gates, gain and restrictions remain undecided.</p>',7)])])}const u=a(t,[["render",r]]);export{m as __pageData,u as default};
